from collections import Counter

class Solution:
    def equalFrequency(self, word: str) -> bool:
        for i in range(len(word)):
            trimmed = word[:i] + word[i + 1:]
            counts = Counter(trimmed)
            if len(set(counts.values())) == 1:
                return True
        return False

class Solution {
public:
    bool equalFrequency(std::string word) {
        int n = word.size();
        for (int i = 0; i < n; i++) {
            std::vector<int> count(26, 0);
            for (int j = 0; j < n; j++) {
                if (j != i) count[word[j] - 'a']++;
            }
            std::unordered_set<int> freqs;
            for (int c : count) {
                if (c > 0) freqs.insert(c);
            }
            if (freqs.size() == 1) return true;
        }
        return false;
    }
};

class Solution {
    public boolean equalFrequency(String word) {
        int n = word.length();
        for (int i = 0; i < n; i++) {
            int[] count = new int[26];
            for (int j = 0; j < n; j++) {
                if (j != i) count[word.charAt(j) - 'a']++;
            }
            java.util.Set<Integer> freqs = new java.util.HashSet<>();
            for (int c : count) {
                if (c > 0) freqs.add(c);
            }
            if (freqs.size() == 1) return true;
        }
        return false;
    }
}

var equalFrequency = function(word) {
    const n = word.length;
    for (let i = 0; i < n; i++) {
        const count = new Array(26).fill(0);
        for (let j = 0; j < n; j++) {
            if (j !== i) count[word.charCodeAt(j) - 97]++;
        }
        const freqs = new Set();
        for (const c of count) {
            if (c > 0) freqs.add(c);
        }
        if (freqs.size === 1) return true;
    }
